function validate([sentence]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 1000) return 'sentence has 1 to 1000 characters.';
  if (!/^[a-z0-9 \-!.,]*$/.test(sentence)) return 'Use only lowercase letters, digits, spaces, hyphens and ! . ,';
  if (sentence.trim() === '') return 'sentence needs at least one token.';
  return null;
}

