function countValidWords(sentence) {
  const isLetter = (ch) => ch >= 'a' && ch <= 'z';
  let count = 0;
  for (const token of sentence.split(' ')) {
    if (token.length === 0) continue;
    let valid = true;
    let hyphens = 0;
    for (let i = 0; i < token.length && valid; i++) {
      const ch = token[i];
      if (ch >= '0' && ch <= '9') {
        valid = false;
      } else if (ch === '-') {
        hyphens++;
        const between = isLetter(token[i - 1]) && isLetter(token[i + 1]);
        valid = hyphens === 1 && between;
      } else if (ch === '!' || ch === '.' || ch === ',') {
        valid = i === token.length - 1;
      }
    }
    if (valid) count++;
  }
  return count;
}

brute:
function countValidWords(sentence) {
  const pattern = /^([a-z]+(-[a-z]+)?)?[!.,]?$/;
  return sentence.trim().split(/ +/).filter(token => token !== '' && pattern.test(token)).length;
}

