function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pickFrom = (text) => text[int(0, text.length - 1)];
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const others = '0123456789-!.,';
  const maxLength = size === 'large' ? int(900, 1000) : int(1, 18);
  const word = () => {
    let text = '';
    const n = int(1, 6);
    for (let i = 0; i < n; i++) text += pickFrom(letters);
    return text;
  };
  const token = () => {
    const roll = rand();
    if (roll < 0.3) return word();
    if (roll < 0.45) return word() + '-' + word() + (rand() < 0.4 ? pickFrom('!.,') : '');
    if (roll < 0.55) return word() + pickFrom('!.,');
    if (roll < 0.62) return pickFrom('!.,-');
    let text = word();
    const extra = int(1, 2);
    for (let i = 0; i < extra; i++) {
      const at = int(0, text.length);
      text = text.slice(0, at) + pickFrom(others) + text.slice(at);
    }
    return text;
  };
  let sentence = rand() < 0.2 ? ' '.repeat(int(1, 2)) : '';
  while (sentence.length < maxLength) sentence += token() + ' '.repeat(int(1, rand() < 0.8 ? 1 : 3));
  sentence = sentence.slice(0, maxLength);
  if (sentence.trim() === '') sentence = pickFrom(letters) + sentence.slice(1);
  return [sentence];
}
